"""FritzBox Router: tests (kit-generated, adapted to the read-only policy). They pass against the emulator;
run them again with the real transport before recording hardware evidence."""
import json
import unittest

from src.adapters.fritzbox_router import (FritzboxRouter, FritzboxRouterBlocked, FritzboxRouterError,
                                          FritzboxRouterTransport, _host_allowed)
from src.adapters.fritzbox_router_emulator import FritzboxRouterEmulator
from src.fabric.fritzbox_router_ingest import ingest_fritzbox_router
from src.fabric.registry import Registry


class FritzboxRouterTests(unittest.TestCase):
    def setUp(self):
        self.emu = FritzboxRouterEmulator()
        self.dev = FritzboxRouter(self.emu)

    def test_facts(self):
        names = {f['name']: f['value'] for f in self.dev.facts()}
        self.assertEqual(names, {'uptime': 172800, 'wan': 'up', 'hosts': 12, 'wifi_clients': 5,
                                 'model': 'FRITZ!Box 7590', 'firmware': '7.59-emulated'})

    def test_every_write_is_refused_by_policy(self):
        for name, value in (('uptime', 1), ('wan', 'down'), ('firmware', '9.9'), ('unknown', 1)):
            with self.subTest(name=name), self.assertRaises(FritzboxRouterBlocked):
                self.dev.set_reversible(name, value)
        for name in ('reboot', 'identify', 'self_destruct'):
            with self.subTest(name=name), self.assertRaises(FritzboxRouterBlocked):
                self.dev.command(name)
        with self.assertRaises(FritzboxRouterBlocked):
            self.dev.undo('uptime')
        self.assertNotIn('write', [h[0] for h in self.emu.history])

    def test_graph_entry_is_pseudonymized_and_labelled_emulated(self):
        reg = Registry()
        self.assertEqual(ingest_fritzbox_router(reg, self.dev, b'salt', 'SERIAL-1234')['status'], 'OK')
        snap = reg.snapshot()
        self.assertNotIn('SERIAL-1234', json.dumps(snap))
        self.assertEqual({c['status'] for d in snap['devices'] for c in d['capabilities']}, {'SIMULATED_VERIFIED'})


class TransportPolicy(unittest.TestCase):
    def test_local_hosts_only(self):
        for host in ('192.168.178.1', '10.0.0.1', '127.0.0.1', 'fritz.box', 'router.lan', 'mybox'):
            self.assertTrue(_host_allowed(host), host)
        for host in ('', '8.8.8.8', 'example.com', 'fritz.box.evil.com', 'a/b'):
            self.assertFalse(_host_allowed(host), host)
        with self.assertRaises(FritzboxRouterBlocked):
            FritzboxRouterTransport('8.8.8.8', 'admin', 'pw')
        with self.assertRaises(FritzboxRouterBlocked):
            FritzboxRouterTransport('192.168.178.1', '', '')

    def test_only_read_calls_are_sent(self):
        t = FritzboxRouterTransport('192.168.178.1', 'admin', 'pw')
        for service, action in (('Hosts', 'SetHost'), ('LANConfigSecurity', 'SetPassword'),
                                ('DeviceInfo', 'Reboot'), ('X_AVM', 'Anything')):
            with self.assertRaises(FritzboxRouterBlocked):
                t.call(service, action)
        with self.assertRaises(FritzboxRouterBlocked):
            t.call('Hosts', 'GetHostNumberOfEntries', {'NewAssociatedDeviceIndex': 0})
        with self.assertRaises(FritzboxRouterBlocked):
            t.write('wan', 'down')
        with self.assertRaises(FritzboxRouterBlocked):
            t.command('reboot')


RESPONSES = {('deviceinfo', 'GetInfo'): ('<u:GetInfoResponse xmlns:u="urn:dslforum-org:service:DeviceInfo:1">'
                                         '<NewUpTime>172800</NewUpTime><NewModelName>FRITZ!Box 7590</NewModelName>'
                                         '<NewSoftwareVersion>7.59</NewSoftwareVersion></u:GetInfoResponse>'),
             ('hosts', 'GetHostNumberOfEntries'): ('<u:GetHostNumberOfEntriesResponse xmlns:u="urn:dslforum-org:service:Hosts:1">'
                                                  '<NewHostNumberOfEntries>12</NewHostNumberOfEntries></u:GetHostNumberOfEntriesResponse>'),
             ('wanipconnection1', 'GetStatusInfo'): ('<u:GetStatusInfoResponse xmlns:u="urn:dslforum-org:service:WANIPConnection:1">'
                                                    '<NewConnectionStatus>Connected</NewConnectionStatus></u:GetStatusInfoResponse>'),
             ('wlanconfig1', 'GetTotalAssociations'): ('<u:GetTotalAssociationsResponse xmlns:u="urn:dslforum-org:service:WLANConfiguration:1">'
                                                      '<NewTotalAssociations>5</NewTotalAssociations></u:GetTotalAssociationsResponse>')}

ENVELOPE = ('<?xml version="1.0"?><s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/">'
            '<s:Body>%s</s:Body></s:Envelope>')


class TransportRoundtrip(unittest.TestCase):
    """The transport against a local fake of the TR-064 API (loopback HTTP server, digest challenged)."""

    @staticmethod
    def serve(auth_ok=True):
        import threading
        from http.server import BaseHTTPRequestHandler, HTTPServer

        class H(BaseHTTPRequestHandler):
            def log_message(self, *_):
                pass

            def do_POST(self):
                ln = int(self.headers.get('Content-Length') or 0)
                raw = self.rfile.read(ln).decode('utf-8', 'replace') if ln else ''
                if not auth_ok or not (self.headers.get('Authorization') or '').startswith('Digest '):
                    self.send_response(401)
                    self.send_header('WWW-Authenticate', 'Digest realm="TR-064", nonce="abc123", qop="auth"')
                    self.send_header('Content-Length', '0')
                    self.end_headers()
                    return
                key = (self.path.rsplit('/', 1)[-1],
                       'GetInfo' if 'GetInfo' in raw else 'GetHostNumberOfEntries' if 'GetHostNumberOfEntries' in raw
                       else 'GetStatusInfo' if 'GetStatusInfo' in raw else 'GetTotalAssociations')
                body = (ENVELOPE % RESPONSES[key]).encode()
                self.send_response(200)
                self.send_header('Content-Type', 'text/xml')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)

        srv = HTTPServer(('127.0.0.1', 0), H)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        return srv

    def test_read_roundtrip(self):
        srv = self.serve()
        try:
            t = FritzboxRouterTransport('127.0.0.1', 'admin', 'secret', port=srv.server_port)
            names = {f['name']: f['value'] for f in FritzboxRouter(t).facts()}
            self.assertEqual(names, {'uptime': 172800, 'wan': 'up', 'hosts': 12, 'wifi_clients': 5,
                                     'model': 'FRITZ!Box 7590', 'firmware': '7.59'})
        finally:
            srv.shutdown()
            srv.server_close()

    def test_bad_password_fails_closed(self):
        srv = self.serve(auth_ok=False)
        try:
            t = FritzboxRouterTransport('127.0.0.1', 'admin', 'wrong', port=srv.server_port)
            with self.assertRaises(FritzboxRouterBlocked):
                FritzboxRouter(t).facts()
        finally:
            srv.shutdown()
            srv.server_close()

    def test_garbage_fails_closed(self):
        import threading
        from http.server import BaseHTTPRequestHandler, HTTPServer

        class H(BaseHTTPRequestHandler):
            def log_message(self, *_):
                pass

            def do_POST(self):
                body = b'<html>not soap'
                self.send_response(200)
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)

        srv = HTTPServer(('127.0.0.1', 0), H)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        try:
            t = FritzboxRouterTransport('127.0.0.1', 'admin', 'secret', port=srv.server_port)
            with self.assertRaises(FritzboxRouterError):
                FritzboxRouter(t).facts()
        finally:
            srv.shutdown()
            srv.server_close()


